function drawHome(){windows.clear();$('.coworker-hover-card')?.remove();syncParticipants();page='home';$('#app').innerHTML=`<header class="topbar">${brand()}<div class="right"></div></header><div class="home-grid">${participantSidebarMarkup()}<main class="home-main"><div class="home-heading"><div class="eyebrow">YOUR WORKSHOP</div><div class="row spread" style="margin-top:12px"><h1 style="margin:0">프로젝트</h1><span class="tag">${current.cards.length} projects</span></div></div><div class="project-grid"><div class="project-card project-add"><button id="new-project"><span class="plus">＋</span><span><strong>새 프로젝트 만들기</strong><small style="display:block;margin-top:6px">이름과 만들고 싶은 이야기를 담아 시작</small></span></button><button id="open-project"><span class="plus">▱</span><span><strong>기존 프로젝트 열기</strong><small style="display:block;margin-top:6px">폴더 선택</small></span></button></div>${current.cards.map(p=>`<article class="project-card" data-project="${esc(p.id)}"><button class="card-menu" data-manage="${esc(p.id)}" aria-label="${esc(p.title)} 관리">···</button><button data-enter="${esc(p.id)}" class="project-card-main"><span class="project-icon">◈</span><span class="project-card-copy"><h2>${esc(p.title)}</h2><p>${esc(p.description||'새로운 제작을 시작할 프로젝트')}</p></span></button><div class="project-card-stats"><div><small>마지막 편집</small><span>${p.updatedAt?esc(new Date(p.updatedAt).toLocaleString('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})):'—'}</span></div><div><small>팩</small><span>—</span></div><div><small>객체</small><span>—</span></div></div></article>`).join('')}</div></main></div>`;$('#app').insertAdjacentHTML('beforeend','<output id="status" hidden role="status"></output>');bindParticipantSidebar();$('#new-project').onclick=createProject;$('#open-project').onclick=openProjectPicker;$$('[data-enter]').forEach(b=>b.onclick=()=>act('openProject',{id:b.dataset.enter}));$$('[data-manage]').forEach(b=>b.onclick=e=>projectMenu(current.cards.find(p=>p.id===b.dataset.manage),e));}
const view=new WebView(connectLocal(),state=>{const changed=current?.projectId!==state.projectId;if(changed)keepInput();current=state;const participantKey=JSON.stringify([state.helpers,state.connections]);if(!changed&&$('.home-side')&&participantKey!==participantSnapshot){syncParticipants();const template=document.createElement('template');template.innerHTML=participantSidebarMarkup();$('.home-side').replaceWith(template.content.firstElementChild);bindParticipantSidebar();}participantSnapshot=participantKey;if(!state.projectId){if(changed||!$('.home-grid'))drawHome();return;}if(changed)drawWork();$('#title').textContent=state.title+' ▾';$('#workspace-label').textContent=state.title.toUpperCase()+' / WORKSPACE';renderObjects();editor();renderEditorViews();renderRetainedEditors();$('#execution-logs').textContent=(state.logs||[]).join('\n');if($('#chat-output'))$('#chat-output').textContent=state.aiOutput||'';$('#helper-summary').textContent=state.helperProfile?state.helperProfile.helper+' · '+state.helperProfile.speciality:'Helper를 명시적으로 선택하세요.';if(windows.has('augment')&&windows.get('augment').meta.snapshot!==JSON.stringify(state.augment))showAugment(true);if(windows.has('worker')){const panel=windows.get('worker'),row=state.workers.find(item=>item.id===panel.meta.workerId);if(row&&panel.meta.snapshot!==JSON.stringify(row))showWorker(row,true);}$('#agent-summary').textContent='⌘ AGENT · '+(state.connection?'설정 선택됨 · '+state.aiState:'미연결');$('#worker-summary').replaceChildren(...(state.workers||[]).map(worker=>{const b=document.createElement('button');b.dataset.operation='worker';const tone=['running','dispatching','awaiting-verification'].includes(worker.status)?'working':['error','interrupted','cancelled'].includes(worker.status)?'problem':'waiting';b.className='consumer-worker';b.innerHTML=`<span class="helper-worker-dot ${tone}" tabindex="0" aria-label="${esc(worker.id)} · ${esc(worker.status)}"><span class="worker-status-tooltip"><strong>${esc(worker.status)}</strong><p>${esc(worker.ownerHelper||'')} · ${esc(worker.goal||'')}</p><small>${esc(worker.progress||worker.blocker||'')}</small></span></span><small>${esc(worker.id)}</small>`;b.onclick=()=>work(async()=>{await view.call('selectWorker',{task:worker.id});showWorker(worker);},'Worker 상태');return b;}));if(changed){const input=retained.get(state.projectId);if(input?.dirty){draft=input.draft;dirty=true;windows.get('source').el.hidden=false;$('#source').value=input.text;$('#selection').textContent=draft.id;editor();}try{for(const saved of JSON.parse(localStorage.getItem('confectory-layout-'+state.projectId)||'[]')){const w=windows.get(saved.key);if(w&&[saved.x,saved.y,saved.width,saved.height].every(Number.isFinite)){Object.assign(w,{x:saved.x,y:saved.y,width:saved.width,height:saved.height,folded:saved.folded===true});w.el.classList.toggle('folded',w.folded);w.el.hidden=saved.hidden===true;clampWindow(w);}}}catch{}}});
function recover(){if(!recovering)recovering=(async()=>{keepInput();await view.dispose();await view.mount();if(windows.has('helpers')&&current.projectId)showHelpers();})().finally(()=>recovering=null);return recovering;}

async function work(action,message){if(busy)return;busy=true;controls();try{await view.update();await action();toast(message);}catch(e){if(['scope_changed','view_closed'].includes(e.message)){await recover();toast('Ready');}else toast(e.message);}finally{busy=false;controls();renderObjects();}}
function act(endpoint,input){if(dirty&&['select','objects','page'].includes(endpoint)&&!(endpoint==='select'&&input.id===draft?.id)){toast('Apply local input before changing selection');return;}return work(async()=>{await view.call(endpoint,input);if(endpoint==='select'&&!dirty&&!['body','project','pack'].includes(view.state.draft?.kind)){await view.call('schema',{id:input.id});showSchema();}},'Ready');}
async function apply(){if(!draft||!dirty)return;if(view.state.draft?.id!==draft.id)throw Error('브라우저에서 편집 중인 객체를 다시 선택하세요. 입력은 유지되었습니다.');await view.call('editDraft',{id:draft.id,text:$('#source').value,revision:draft.revision});dirty=false;draft=view.state.draft;$('#source').value=draft.text;await view.update();}
function bindCommon(){const objects=$('#objects-refresh');if(objects)objects.onclick=()=>{browser();act('objects',{});};const reconnect=$('#reconnect');if(reconnect)reconnect.onclick=()=>{if(dirty){toast('Apply local input before reconnecting');return;}return work(async()=>{await view.dispose();await view.mount();},'Reconnected; shared draft retained');};}
let updating=false;setInterval(async()=>{if(updating||!view.active)return;updating=true;try{await view.update();}catch(e){if(e.message==='scope_changed')await recover();else toast(e.message);}finally{updating=false;}},100);
