function createProject(){let parent=null;modal('새 프로젝트 만들기',`<form id="create-form"><div class="field"><label for="project-name">프로젝트 이름 <span style="color:var(--accent)">*</span></label><input id="project-name" required placeholder="예: Forest Adventure" maxlength="60"></div><div class="field"><label for="project-desc">어떤 프로젝트를 만들고 싶나요?</label><textarea id="project-desc" rows="3" placeholder="작은 숲을 탐험하고 재료를 모으는 게임을 만들고 싶어요."></textarea></div><div class="field"><label>프로젝트 생성 위치</label><div class="row spread"><span id="parent" class="small">Parent · 생성 시 폴더 선택</span><button type="button" class="secondary" id="choose-parent" disabled title="현재 호스트는 생성 요청 시 폴더를 선택합니다">폴더 선택</button></div><div class="path-preview" id="destination">Destination · 생성 시 결정</div></div><div class="fields"><div class="field"><label>Main Helper</label><select id="main-helper" disabled><option>생성 후 선택</option></select></div><div class="field"><label>Main Agent</label><select id="main-agent" disabled><option>생성 후 선택</option></select></div></div><details><summary style="font-size:14px;cursor:pointer">고급 설정 · 팩 구성</summary><div class="editor-note"><label><input type="checkbox" checked disabled> ProjectPack · 기본 포함</label><br><label><input type="checkbox" id="game-pack" disabled> 기본 게임 팩</label><div style="margin-top:10px"><button type="button" id="recommend" disabled title="팩 추천 계약 미연결" class="secondary">설명으로 팩 추천</button></div><p id="pack-recommend"></p></div></details><div class="actions"><button class="primary" type="submit">프로젝트 생성</button></div></form>`,(r,close)=>{const submit=$('button[type="submit"]',r),choose=$('#choose-parent',r);choose.disabled=!globalThis.confectoryWebUI?.chooseProjectParent;choose.onclick=async()=>{choose.disabled=true;try{const reply=await globalThis.confectoryWebUI.chooseProjectParent();if(!reply.ok)throw Error(reply.error?.code||'picker_failed');if(!reply.cancelled){parent=reply.parent;$('#parent',r).textContent='Parent · '+reply.label;$('#destination',r).textContent='Destination · '+reply.label+'/'+$('#project-name',r).value;}}catch(e){toast(e.message);}finally{choose.disabled=false;}};$('#project-name',r).oninput=()=>{if(parent)$('#destination',r).textContent=$('#parent',r).textContent.replace('Parent · ','Destination · ')+'/'+$('#project-name',r).value;};submit.disabled=!globalThis.confectoryWebUI?.createProject;if(submit.disabled){$('#destination',r).textContent='현재 호스트는 프로젝트 생성을 지원하지 않습니다.';}$('#create-form',r).onsubmit=e=>{e.preventDefault();const name=$('#project-name',r).value.trim(),description=$('#project-desc',r).value;if(!name||!globalThis.confectoryWebUI?.createProject)return;submit.disabled=true;work(async()=>{const reply=await globalThis.confectoryWebUI.createProject(name,description,parent);if(!reply.ok)throw Error(reply.error?.code||'create_failed');if(!reply.cancelled){close();await recover();}},'프로젝트 생성 요청 처리됨').finally(()=>{if(submit.isConnected)submit.disabled=false;});};});}

