function modal(title,html,onMount){const previous=document.activeElement;$('#overlays').innerHTML=`<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button data-close aria-label="닫기">×</button></div>${html}</section></div>`;const root=$('.modal'),close=()=>{$('#overlays').innerHTML='';previous?.focus();};$('[data-close]',root).onclick=close;$('.modal-shade').onclick=e=>{if(e.target===e.currentTarget)close();};root.onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const items=$$('button,input,select,textarea,[tabindex="0"]',root).filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}};onMount?.(root,close);($('input:not(:disabled)',root)||$('[data-close]',root)).focus();}
