for(const b of $$('[data-participant-toggle]')){const key=b.dataset.participantToggle,section=b.closest('.participant-section');const apply=()=>{const closed=key==='coworker'?(db.coworkerDockCollapsed??true):!!db.participantCollapsed?.[key];section.classList.toggle('section-collapsed',closed);section.querySelector('.participant-grid').hidden=closed;b.setAttribute('aria-expanded',String(!closed));if(key==='coworker')$('.coworker-sidebar-shade').hidden=closed;};b.onclick=()=>{db.participantCollapsed??={};if(key==='coworker')db.coworkerDockCollapsed=!(db.coworkerDockCollapsed??true);else db.participantCollapsed[key]=!db.participantCollapsed[key];apply();persist();};apply();}
