function participantSectionStart(key,label){return `<section class="participant-section"><button class="participant-section-toggle" data-participant-toggle="${key}" aria-label="${esc(label)}" title="${esc(label)}" aria-expanded="true" aria-controls="participant-${key}"><span class="participant-heading-label">${participantHeadingIcon(key)}<span class="participant-category-name">${label.split("(")[0].trim()}</span><span class="participant-category-count">${label.slice(label.indexOf("("))}</span>${participantHasNews(key)?'<span class="news-orb" role="img" aria-label="새 소식"></span>':''}</span><svg class="section-chevron" viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button>`}

function participantSection(key,label,content){return participantSectionStart(key,label)+`<div class="participant-grid" id="participant-${key}">${content}</div></section>`}

function participantSidebarMarkup(){return `<aside class="home-side" id="home-participants"><button class="home-side-toggle" id="home-side-toggle" aria-controls="home-participants" aria-expanded="true" aria-label="작업 참여자 접기">‹</button><div class="participants-scroll">${participantSection('agent','AGENT ('+(current.connections||[]).length+')',agentHomeTiles())}${participantSectionStart('helper','HELPER ('+helpers.length+')')}<div class="participant-grid" id="participant-helper">${helperAgentGroups()}<button class="participant-add helper-home" id="add-helper" aria-label="Helper 추가"><span class="avatar add-avatar">＋</span><span class="meta"><strong>Helper 추가</strong></span></button></div></section></div><div class="coworker-sidebar-shade" hidden aria-hidden="true"></div><div class="coworker-bottom-dock">${participantSection('coworker','User('+0+'/'+0+')','<button type="button" class="coworker-drawer-close" aria-label="Coworker 목록 닫기"><svg viewBox="0 0 24 12" aria-hidden="true"><path d="m4 3 8 6 8-6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><input type="search" id="friend-search" class="friend-search" aria-label="친구 검색" placeholder="친구 검색" autocomplete="off"><button type="button" id="add-friend" class="friend-add-button">＋ 친구 추가</button><div class="coworker-list" aria-label="친구 목록">'+coworkerTiles()+'</div>')}</div></aside>`}

function setupParticipantResize(){const side=document.querySelector('.home-side'),layout=side.parentElement;const min=100,max=360;const handle=document.createElement('div');handle.className='participant-resizer';handle.tabIndex=0;handle.setAttribute('role','separator');handle.setAttribute('aria-label','사이드바 너비 조절, 클릭하여 최소화 또는 복원');handle.setAttribute('aria-orientation','vertical');handle.setAttribute('aria-valuemin',min);handle.setAttribute('aria-valuemax',max);side.append(handle);const observer=new ResizeObserver(()=>{if(!side.isConnected){observer.disconnect();return}const actual=side.getBoundingClientRect().width;side.classList.toggle('is-wide-sidebar',actual>=120);side.style.setProperty('--participant-columns',actual>=270?3:actual>=180?2:1)});observer.observe(side);const apply=value=>{const width=Math.max(min,Math.min(max,value));db.participantSidebarWidth=width;side.classList.toggle('is-wide-sidebar',width>=120);layout.style.setProperty('--participant-width',width+'px');side.style.setProperty('--participant-columns',width>=270?3:width>=180?2:1);handle.setAttribute('aria-valuenow',width);};if(!db.compactSidebarV2){if(!db.participantSidebarWidth||db.participantSidebarWidth===144)db.participantSidebarWidth=min;db.compactSidebarV2=true}if(!db.sidebarMin80){if(db.participantSidebarWidth===120)db.participantSidebarWidth=80;db.sidebarMin80=true}if(!db.sidebarMin90){if(db.participantSidebarWidth===80)db.participantSidebarWidth=90;db.sidebarMin90=true}if(!db.sidebarDefault180){db.participantSidebarWidth=180;db.sidebarDefault180=true}apply(db.participantSidebarWidth??180);handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();handle.setPointerCapture(e.pointerId);const x=e.clientX,width=db.participantSidebarWidth??min;let moved=false;handle.onpointermove=ev=>{if(!moved&&Math.abs(ev.clientX-x)<4)return;if(!moved&&db.homeSidebarCollapsed)$('#home-side-toggle').click();moved=true;apply(width+ev.clientX-x)};const end=ev=>{if(ev.type==='pointerup'&&!moved)$('#home-side-toggle').click();handle.onpointermove=null;handle.onpointerup=null;handle.onpointercancel=null;persist();if(page==='work')clampWindows()};handle.onpointerup=end;handle.onpointercancel=end};handle.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#home-side-toggle').click();return}if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();apply(e.key==='Home'?min:e.key==='End'?max:db.participantSidebarWidth+(e.key==='ArrowRight'?10:-10));persist();if(page==='work')clampWindows()};}

function openAppSettings(){modal('설정','<div class="app-settings-content"><h3>화면</h3><div class="field"><label for="settings-sidebar-width">사이드바 너비</label><div class="row"><input id="settings-sidebar-width" type="range" min="100" max="360" step="1" value="'+(db.participantSidebarWidth??144)+'"><output id="settings-sidebar-value">'+(db.participantSidebarWidth??144)+'px</output></div><small>너비에 따라 1~3열로 표시됩니다.</small></div></div>',root=>{root.querySelector('#settings-sidebar-width').oninput=e=>{const width=Number(e.target.value);db.participantSidebarWidth=width;const side=document.querySelector('.home-side');side.parentElement.style.setProperty('--participant-width',width+'px');side.style.setProperty('--participant-columns',width>=270?3:width>=180?2:1);side.querySelector('.participant-resizer').setAttribute('aria-valuenow',width);root.querySelector('output').textContent=width+'px';persist();if(page==='work')clampWindows()}})}

function setupChatResize(){const bar=document.querySelector('.chatbar');bar.querySelector('.chat-tabs small')?.remove();bar.querySelector('#collapse-chat')?.remove();const handle=document.createElement('div');handle.className='chatbar-resizer';handle.tabIndex=0;handle.setAttribute('role','separator');handle.setAttribute('aria-label','채팅바 높이 조절');handle.setAttribute('aria-orientation','horizontal');bar.prepend(handle);const apply=value=>{const max=Math.max(44,Math.floor(Math.min(bar.parentElement.clientHeight*.7,bar.parentElement.clientHeight-280)));const height=Math.max(44,Math.min(max,value));bar.style.height=height+'px';bar.classList.toggle('is-minimized',height<=48);handle.setAttribute('aria-valuemin','44');handle.setAttribute('aria-valuemax',String(max));handle.setAttribute('aria-valuenow',String(height));return height};let height=apply(db.chatbarHeight||180);let restoreHeight=db.chatbarRestoreHeight||180;handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();const y=e.clientY,initial=bar.getBoundingClientRect().height;let dragged=false;handle.setPointerCapture(e.pointerId);handle.onpointermove=ev=>{if(!dragged&&Math.abs(ev.clientY-y)<4)return;dragged=true;height=apply(initial+y-ev.clientY);clampWindows()};const finish=event=>{if(!dragged&&event.type!=='pointercancel'){if(initial>48){restoreHeight=initial;height=apply(44)}else height=apply(restoreHeight);clampWindows()}if(height>48)restoreHeight=height;db.chatbarRestoreHeight=restoreHeight;handle.onpointermove=null;handle.onpointerup=null;handle.onpointercancel=null;db.chatbarHeight=height;persist()};handle.onpointerup=finish;handle.onpointercancel=finish};handle.onkeydown=e=>{if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();height=apply(e.key==='Home'?44:e.key==='End'?innerHeight:e.key==='ArrowUp'?height+10:height-10);db.chatbarHeight=height;persist();clampWindows()}}

await view.mount();busy=true;controls();try{await view.call(current.projectId?'helperList':'globalHelpers',{});}finally{busy=false;controls();}if($('#status'))$('#status').textContent='Ready';

function showReview(){const review=view.state.review;if(!review){toast('Review unavailable');return;}const w=openWindow('review','Source Review · 최종 반영 확인',680,490),ids=(review.units||[]).map(unit=>unit.id);w.body.innerHTML=`<div class="window-content"><h2>${esc(ids.join(' · '))}</h2><p>검토한 변경만 최종 소스에 반영합니다. 새 선언은 프로젝트 등록 변경도 함께 선택해야 합니다.</p>${review.units.map(unit=>`<details><summary>${esc(unit.id)} · 고급 소스 비교</summary><h3>Before</h3><pre class="consumer-output">${esc(unit.before)}</pre><h3>After</h3><pre class="consumer-output">${esc(unit.after)}</pre></details>`).join('')}<button id="confirm" data-operation data-token="${esc(review.token)}">Confirm · 검토한 소스 반영</button></div>`;$('#confirm').onclick=()=>work(async()=>{await view.call('confirmGroup',{token:review.token,ids});reviewSelections.delete(current.projectId);closeWindow('review');},'Source confirmed');controls();}
function showSchema(schema=view.state.schema,detached=null,refresh=false){
if(!schema){toast('Schema unavailable');return;}
 const scope=current.projectId,revision=schema.revision,w=openWindow(detached?'editor-'+detached.view:'schema','스키마 · '+schema.id,520,450,{refresh});w.meta.id=schema.id;if(detached)w.meta.view=detached.view;
 w.body.innerHTML=`<div class="window-content"><h2 data-schema-id>${esc(schema.id)}</h2><p>${esc(schema.description||'')}</p><p class="small">의미 객체 속성과 유효 스키마 · 필드 변경은 공유 초안에만 반영됩니다.</p><div data-schema-fields></div><div class="actions"><button data-operation id="semantic-save">Save · 작업 사본</button><button data-operation id="semantic-review">Review</button></div></div>`;
 $('#semantic-save',w.body).onclick=()=>work(()=>{if([...schemaInputs.keys()].some(key=>key.startsWith(current.projectId+'|'+schema.id+'|')))throw Error('필드 입력을 먼저 적용하세요. 입력은 유지됩니다.');return view.call(detached?'saveEditorView':'saveDraft',detached?{view:detached.view,id:schema.id}:{});},'Draft saved; final sources unchanged');$('#semantic-review',w.body).hidden=!!detached;$('#semantic-review',w.body).onclick=()=>work(async()=>{if(dirty||[...schemaInputs.keys()].some(key=>key.startsWith(current.projectId+'|'+schema.id+'|')))throw Error('미적용 입력을 먼저 적용하세요. 입력은 유지됩니다.');await view.call('reviewDraft',{id:schema.id,target:targetChoices.get(current.projectId)||current.runTarget});showReview();},'Review ready; final sources unchanged');
 const container=$('[data-schema-fields]',w.body);
 const origins=[...new Set(schema.rows.map(row=>row.schemaOrigin).filter(id=>typeof id==='string'&&id!==schema.id))];if(origins.length){const links=document.createElement('div');links.className='actions';for(const id of origins){const button=document.createElement('button');button.dataset.operation='schema-origin';button.dataset.schemaOrigin=id;button.textContent='필드 정의 스키마 열기 · '+id;button.onclick=()=>act('select',{id});links.append(button);}container.append(links);}
 const metadata=Object.entries(schema.values||{}).filter(([,value])=>value!==null&&['string','number','boolean'].includes(typeof value)).map(([name,value])=>({metadata:true,name,type:typeof value,inputKind:typeof value==='string'?'text':typeof value==='boolean'?'boolean':'number',path:[name],value,writable:true}));
 if(schema.kind==='schema')renderDefinitions(schema,detached,w);
 for(const row of [...(schema.kind==='schema'?[]:schema.rows),...metadata]){
  const key=scope+'|'+schema.id+'|'+(detached?'view:'+detached.view+'|':'primary|')+(row.metadata?'metadata:':'')+JSON.stringify(row.path),pending=schemaInputs.get(key);let baseRevision=pending?.revision??revision;const field=document.createElement('div');field.className='field';
  const label=document.createElement('label');label.textContent=row.path.map(part=>typeof part==='number'?'['+part+']':part).join(' / ')+' · '+row.type;field.append(label);field.style.marginLeft=Math.min(48,(row.path.length-1)*12)+'px';
  const simple=['text','number','boolean','reference','function'].includes(row.inputKind)&&row.writable;
  const baseline=String((['reference','function'].includes(row.inputKind)?row.reference:row.value)??''),input=document.createElement('input');input.type=row.inputKind==='boolean'?'checkbox':row.inputKind==='number'?'number':'text';if(input.type==='number')input.step='any';
  input.dataset.schemaField=row.name;input.dataset.supported=String(simple);input.value=pending?.text??baseline;if(input.type==='checkbox')input.checked=input.value==='true';input.disabled=!simple;input.setAttribute('aria-label',row.name);field.append(input);
  input.oninput=()=>{if(input.type==='checkbox')input.value=String(input.checked);if(input.value===baseline)schemaInputs.delete(key);else schemaInputs.set(key,{text:input.value,revision:baseRevision});};
  if(simple){
   const applyButton=document.createElement('button');applyButton.textContent='Apply field';applyButton.dataset.operation='field';
   applyButton.onclick=()=>work(async()=>{if(dirty)throw Error('Apply source input before editing fields');if(current.projectId!==scope||(!detached&&view.state.draft?.id!==schema.id))throw Error('Schema selection changed');let value=input.type==='checkbox'?input.checked:row.inputKind==='number'?Number(input.value):['reference','function'].includes(row.inputKind)?{$ref:input.value}:input.value;if(row.inputKind==='number'&&(input.value.trim()===''||!Number.isFinite(value)))throw Error('유효한 숫자를 입력하세요. 입력은 유지됩니다.');const expected=schemaInputs.get(key)?.revision??revision;await view.call(detached?(row.metadata?'editViewMetadata':'editViewField'):row.metadata?'editMetadata':'editField',{...(detached?{view:detached.view}:{}),id:schema.id,path:row.path,field:row.name,value,revision:expected});schemaInputs.delete(key);if(!detached){await view.call('schema',{id:schema.id});showSchema();}else{w.meta.schemaStamp=null;renderEditorViews();}},'Shared field draft updated');field.append(applyButton);
   const reset=document.createElement('button');reset.textContent='현재 값으로 되돌리기';reset.dataset.operation='reset-field';reset.onclick=()=>{schemaInputs.delete(key);baseRevision=revision;input.value=baseline;if(input.type==='checkbox')input.checked=baseline==='true';};field.append(reset);
  }else{const note=document.createElement('small');note.textContent=detached&&row.metadata?'메타데이터는 기본 속성창에서 편집합니다.':row.inputKind==='list'?'아래 기존 항목을 개별 편집합니다. 삽입·재정렬은 계약 미정입니다.':row.inputKind==='group'?'아래 구성 필드를 개별 편집합니다.':'현재 경로는 읽기 전용입니다.';field.append(note);}
  container.append(field);
 }
 if(detached){const release=document.createElement('button');release.textContent='창 해제';release.dataset.operation='release-view';release.onclick=()=>work(async()=>{if([...schemaInputs.keys()].some(key=>key.startsWith(scope+'|'+schema.id+'|view:'+detached.view+'|')))throw Error('미적용 입력을 먼저 적용하세요.');await view.call('closeEditorView',{view:detached.view,id:schema.id});w.el.remove();windows.delete(w.key);renderRetainedEditors();},'독립 뷰 해제 · 공유 초안 유지');w.body.append(release);}
 controls();
}

function showHelpers(){
 const selectedHelper=current.helperProfile?.helper,memoryKey=current.projectId+'|'+(selectedHelper||'');const w=openWindow('helpers','Helper · 프로필과 기억 범위',510,460);
 w.body.innerHTML=`<div class="window-content"><p>모집과 기억은 로컬 저장입니다. AI 연결과 전송은 별도로 검토합니다.</p><div class="actions"><button data-operation data-recruit="global">공통 Helper 모집</button><button data-operation data-recruit="project">프로젝트 Helper 모집</button></div><div id="helper-list"></div><label><input type="checkbox" id="allow-common" ${current.allowCommon?'checked':''}> 이 프로젝트에 공통 기억 허용</label><p>기억 대상: ${esc(selectedHelper||'선택하지 않음')}</p><textarea id="helper-memory" maxlength="2048" placeholder="명시적으로 기억할 내용">${esc(helperMemoryInputs.get(memoryKey)||'')}</textarea><select id="memory-scope"><option value="project">현재 프로젝트 기억</option><option value="common">공통 기억</option></select><button data-operation id="remember">기억 저장</button></div>`;
 for(const helper of current.helpers||[]){const row=document.createElement('div');row.className='field';const p=document.createElement('p');p.textContent=helper.id+' · '+helper.membership+'\n'+helper.personality+' / '+helper.speciality;row.append(p);const b=document.createElement('button');b.dataset.operation='helper';b.textContent='이 프로젝트에 선택';b.onclick=()=>work(async()=>{await view.call('helperConnect',{helper:helper.id,allowCommon:$('#allow-common').checked});await recover();showHelpers();},'Helper 범위 선택됨');row.append(b);$('#helper-list').append(row);}
 $$('[data-recruit]').forEach(b=>b.onclick=()=>work(async()=>{await view.call('helperRecruit',{kind:b.dataset.recruit});showHelpers();},'로컬 Helper 모집됨'));
 $('#allow-common').onchange=()=>work(async()=>{await view.call('helperCommon',{enabled:$('#allow-common').checked});await recover();showHelpers();},'공통 기억 권한 변경됨');
 $('#helper-memory').oninput=()=>helperMemoryInputs.set(memoryKey,$('#helper-memory').value);$('#remember').onclick=()=>work(async()=>{await view.call('helperRemember',{helper:selectedHelper,scope:$('#memory-scope').value,text:$('#helper-memory').value});helperMemoryInputs.delete(memoryKey);showHelpers();},'기억이 로컬에 저장됨');controls();
}
function showConnections(){const w=openWindow('connections','AI 연결 팩 · 로컬 선택',500,400);w.body.innerHTML='<div class="window-content"><p>이미 구성한 연결 팩만 선택합니다. 자격 증명·계정 인증·유료 호출은 이 작업에서 보류합니다.</p><div id="connection-list"></div></div>';for(const connection of current.connections||[]){const b=document.createElement('button');b.dataset.operation='connection';b.textContent=connection.id;b.onclick=()=>work(()=>view.call('bindConnection',{connection:connection.id}),'연결 팩이 로컬에 선택됨 · 전송 없음');$('#connection-list').append(b);}controls();}

function showChat(){const scope=current.projectId,body=$('#chat-inner');body.hidden=false;$('#execution-logs').hidden=true;$('#chat').classList.add('selected');$('#logs-tab').classList.remove('selected');if($('#chat-input'))return;body.innerHTML=`<div class="messages" id="messages"><div class="message"><strong>${esc(current.helperProfile?.helper||'')}</strong><span id="chat-output">${esc(current.aiOutput||'')}</span></div></div><form class="chat-compose" id="chat-form"><textarea id="chat-input" maxlength="4096" aria-label="프로젝트 채팅 입력" placeholder="함께 만들 내용을 남겨보세요…">${esc(conversations.get(scope)??current.chatDraft??'')}</textarea><button class="primary" data-operation id="chat-prepare" type="submit" aria-label="메시지 보내기">보내기</button></form>`;
$('#chat-input').oninput=()=>conversations.set(scope,$('#chat-input').value);
$('#chat-input').onblur=e=>{if($('#chat-form').contains(e.relatedTarget)||e.relatedTarget?.closest('.brand')||current.projectId!==scope||busy)return;const value=$('#chat-input')?.value;if(value!==undefined&&value!==current.chatDraft)work(()=>view.call('chatDraft',{value}),'프로젝트 대화 초안 저장됨 · 전송 없음');};
$('#chat-form').onsubmit=e=>{e.preventDefault();work(async()=>{const value=$('#chat-input').value;await view.call('chatDraft',{value});await view.call('prepareAI',{kind:'chat',message:value});showPreview();},'전송 전 검토 준비됨 · 전송 없음');};controls();}

function showPreview(){
 const preview=current.aiPreview;if(!preview)return;const w=openWindow('ai-preview','AI 전송 전 검토',640,500),token=preview.token;
 w.body.innerHTML=`<div class="window-content"><p>${esc(preview.connection)} · ${esc(preview.kind)} · ${esc(preview.target||'')}</p><pre class="consumer-output">${esc(preview.message)}</pre><p>${esc(preview.rights)}</p><details><summary>이번 전송의 Helper 범위와 기억</summary><pre class="consumer-output">${esc(JSON.stringify(preview.helperContext,null,2))}</pre></details><details><summary>모델·호출 제한</summary><pre class="consumer-output">${esc(JSON.stringify({pins:preview.pins,limits:preview.limits},null,2))}</pre></details><p>${esc((preview.disclosures||[]).join(' '))}</p><div id="permission-choices"></div><p>${preview.canStart?'':esc(preview.blockedReason||'이 대상에서 실행 지원이 확인되지 않았습니다.')}</p><button data-operation id="ai-start" data-token="${esc(token)}" data-supported="false">승인한 내용으로 시작</button><button data-operation id="cancel-preview">검토 취소</button></div>`;
 for(const requirement of preview.requirements||[]){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.permission=requirement.id;input.dataset.operation='permission-choice';input.checked=preview.approvals?.[requirement.id]===true;input.onchange=()=>work(async()=>{await view.call('permission',{token,id:requirement.id,approved:input.checked});previewControls();},'이번 전송 권한 선택됨 · 아직 전송 없음');label.append(input,document.createTextNode(requirement.label||requirement.id));$('#permission-choices').append(label);}
 $('#ai-start').onclick=()=>work(async()=>{if(current.aiPreview?.token!==token)throw Error('전송 검토가 변경되었습니다. 다시 검토하세요.');await view.call('startAI',{token});closeWindow('ai-preview');},preview.kind==='adoption-record'?'로컬 채택 기록 확인됨 · 전송 없음':'승인된 AI 요청 시작됨 · 최종 소스 반영은 별도 검토');$('#cancel-preview').onclick=()=>work(async()=>{await view.call('cancelPreview',{});closeWindow('ai-preview');},'검토 취소됨 · 전송 없음');previewControls();controls();
}
function previewControls(){const button=$('#ai-start'),preview=current?.aiPreview;if(!button)return;button.dataset.supported=String(button.dataset.token===preview?.token&&preview?.canStart===true&&(preview.requirements||[]).every(r=>preview.approvals?.[r.id]===true));button.disabled=busy||button.dataset.supported==='false';}
